export function Divider({
  orientation = "{{orientation}}",
  thickness = {{thickness}},
  color = "{{color}}",
  label = "{{label}}",
  inset = {{inset}},
}) {
  const vertical = orientation === "vertical";
  return (
    <div style={{ display: "flex", flexDirection: vertical ? "row" : "column", alignItems: "center", fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", background: "#FAF7F2", padding: 16, height: vertical ? 90 : "auto" }}>
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", background: "#fff", border: "1px solid #24143018", borderRadius: 6, padding: 14 }}>Section A</div>
      <div style={{ position: "relative", display: "flex", alignItems: "center", justifyContent: "center", flex: "none", width: vertical ? "auto" : "100%", height: vertical ? "100%" : "auto", padding: vertical ? "0 8px" : "8px 0" }}>
        <span style={{ background: color, width: vertical ? thickness : "100%", height: vertical ? "100%" : thickness }} />
        {inset && <span style={{ position: "absolute", background: "#FAF7F2", padding: "0 8px", fontWeight: 700, fontSize: 11, color }}>{label}</span>}
      </div>
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", background: "#fff", border: "1px solid #24143018", borderRadius: 6, padding: 14 }}>Section B</div>
    </div>
  );
}
